package com.icewright.generated.service;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.icewright.generated.config.Settings;
import jakarta.annotation.PreDestroy;
import org.springframework.stereotype.Service;
import redis.clients.jedis.DefaultJedisClientConfig;
import redis.clients.jedis.HostAndPort;
import redis.clients.jedis.JedisPooled;
import redis.clients.jedis.params.ScanParams;
import redis.clients.jedis.params.SetParams;
import redis.clients.jedis.resps.ScanResult;

import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 会话槽位存储：Redis 只存易失会话状态，不落任何业务数据。
 *
 * @author IceWright builder
 */
@Service
public class SessionService {

    private static final int SLOTS_TTL_SECONDS = 3600;
    private static final int SOCKET_TIMEOUT_MILLIS = 3000;
    private static final String KEY_TEMPLATE = "iw:%s:%s";

    private final ObjectMapper mapper = new ObjectMapper();
    private final JedisPooled jedis = new JedisPooled(
        new HostAndPort(Settings.REDIS_HOST, Settings.REDIS_PORT),
        DefaultJedisClientConfig.builder()
            .password(resolvePassword())
            .connectionTimeoutMillis(SOCKET_TIMEOUT_MILLIS)
            .socketTimeoutMillis(SOCKET_TIMEOUT_MILLIS)
            .build());

    private static String resolvePassword() {
        return Settings.REDIS_PASSWORD.isEmpty() ? null : Settings.REDIS_PASSWORD;
    }

    private String key(String sessionId) {
        return String.format(KEY_TEMPLATE, Settings.PROJECT, sessionId);
    }

    public String redisPing() {
        try {
            jedis.ping();
            return "ok";
        } catch (RuntimeException e) {
            // 健康检查须吞掉一切连接异常
            return "unreachable";
        }
    }

    public Map<String, Object> loadSlots(String sessionId) {
        String raw = jedis.get(key(sessionId));
        if (raw == null || raw.isEmpty()) {
            return new LinkedHashMap<>();
        }
        try {
            Object parsed = mapper.readValue(raw, new TypeReference<Object>() {
            });
            if (parsed instanceof Map<?, ?> map) {
                @SuppressWarnings("unchecked")
                Map<String, Object> slots = (Map<String, Object>) map;
                return new LinkedHashMap<>(slots);
            }
            return new LinkedHashMap<>();
        } catch (java.io.IOException e) {
            return new LinkedHashMap<>();
        }
    }

    public void saveSlots(String sessionId, Map<String, Object> slots) {
        try {
            String payload = mapper.writeValueAsString(slots);
            jedis.set(key(sessionId), payload, SetParams.setParams().ex(SLOTS_TTL_SECONDS));
        } catch (java.io.IOException e) {
            throw new IllegalStateException("槽位序列化失败", e);
        }
    }

    public Map<String, Object> mergeSlots(String sessionId, Map<String, Object> patch) {
        Map<String, Object> slots = loadSlots(sessionId);
        slots.putAll(patch);
        saveSlots(sessionId, slots);
        return slots;
    }

    /**
     * 枚举本项目全部会话槽位（SCAN 非 KEYS，不阻塞 Redis）；只读，不落业务数据。
     *
     * @return 每项为 {session_id, slots} 的有序 Map
     */
    public List<Map<String, Object>> listSessions() {
        String prefix = String.format(KEY_TEMPLATE, Settings.PROJECT, "");
        List<Map<String, Object>> out = new ArrayList<>();
        String cursor = ScanParams.SCAN_POINTER_START;
        do {
            ScanResult<String> page = jedis.scan(cursor, new ScanParams().match(prefix + "*").count(100));
            for (String key : page.getResult()) {
                String sessionId = key.substring(prefix.length());
                Map<String, Object> row = new LinkedHashMap<>();
                row.put("session_id", sessionId);
                row.put("slots", loadSlots(sessionId));
                out.add(row);
            }
            cursor = page.getCursor();
        } while (!ScanParams.SCAN_POINTER_START.equals(cursor));
        return out;
    }

    @PreDestroy
    public void close() {
        jedis.close();
    }
}
